"""Run with: python3 -I -m unittest discover -s .github/scripts"""
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import threading
import time
import unittest

import soclaas_review as sr


class FakeSoclaas:
    """Answers each request with the next planned reply: 'slow', an HTTP status (502, 503, 504),
    ('sse', [chunk, ...]) for a streamed answer, or a completion's text as plain JSON."""

    def __init__(self, plan):
        self.plan, self.calls, self.bodies = list(plan), 0, []
        fake = self

        class Handler(BaseHTTPRequestHandler):
            def log_message(self, *args):
                pass

            def do_POST(self):
                fake.bodies.append(json.loads(self.rfile.read(int(self.headers.get('Content-Length', 0))) or b'{}'))
                fake.calls += 1
                step = fake.plan.pop(0)
                if step == 'slow':
                    time.sleep(1)  # longer than the tests' timeout
                    return
                if isinstance(step, int):
                    self.send_response(step)
                    self.end_headers()
                    return
                # AI-generated by Claude Code (review pending): a Chat Completions stream.
                if isinstance(step, tuple) and step[0] == 'sse':
                    self.send_response(200)
                    self.send_header('Content-Type', 'text/event-stream')
                    self.end_headers()
                    for chunk in step[1]:
                        line = chunk if isinstance(chunk, str) else json.dumps(chunk)
                        self.wfile.write(f'data: {line}\n\n'.encode())
                        self.wfile.flush()
                    return
                body = json.dumps({'choices': [{'message': {'content': step}, 'finish_reason': 'stop'}]}).encode()
                self.send_response(200)
                self.send_header('Content-Type', 'application/json')
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)

        self.server = ThreadingHTTPServer(('127.0.0.1', 0), Handler)
        self.server.daemon_threads = True
        threading.Thread(target=self.server.serve_forever, daemon=True).start()
        self.client = sr.JsonClient(f'http://127.0.0.1:{self.server.server_port}/v1', 'token', 'SoCLaaS')

    def close(self):
        self.server.shutdown()
        self.server.server_close()


# AI-generated by Claude Code (reviewed by Jian Bing)
class TimeoutTests(unittest.TestCase):
    def setUp(self):
        self.saved = sr.REVIEW_TIMEOUT, sr.RETRY_PAUSE
        sr.REVIEW_TIMEOUT, sr.RETRY_PAUSE = 0.3, 0

    def tearDown(self):
        sr.REVIEW_TIMEOUT, sr.RETRY_PAUSE = self.saved
        self.fake.close()

    def test_a_slow_answer_is_reported_as_a_timeout_not_as_unreachable(self):
        self.fake = FakeSoclaas(['slow'])
        with self.assertRaises(sr.ReviewError) as caught:
            self.fake.client.request('POST', '/chat/completions', {}, timeout=0.3)
        self.assertIn('did not answer within', str(caught.exception))
        self.assertNotIn('could not be reached', str(caught.exception))

    def test_the_review_request_is_retried_once_after_a_timeout(self):
        self.fake = FakeSoclaas(['slow', 'looks fine'])
        self.assertEqual(sr.completion_text(sr.request_review(self.fake.client, {})), 'looks fine')
        self.assertEqual(self.fake.calls, 2)

    def test_the_review_request_is_retried_once_after_a_503(self):
        self.fake = FakeSoclaas([503, 'looks fine'])
        self.assertEqual(sr.completion_text(sr.request_review(self.fake.client, {})), 'looks fine')
        self.assertEqual(self.fake.calls, 2)

    def test_it_gives_up_after_the_second_timeout(self):
        self.fake = FakeSoclaas(['slow', 'slow'])
        with self.assertRaises(sr.ReviewError) as caught:
            sr.request_review(self.fake.client, {})
        self.assertIn('did not answer within', str(caught.exception))
        self.assertEqual(self.fake.calls, 2)


def chunk(content=None, finish=None):
    delta = {} if content is None else {'content': content}
    return {'choices': [{'index': 0, 'delta': delta, 'finish_reason': finish}]}


# AI-generated by Claude Code (review pending)
class StreamingTests(unittest.TestCase):
    """SoCLaaS's gateway answers 502 when a request is still waiting after about two minutes, so the
    review is streamed: the answer arrives piece by piece and the connection is never idle that long."""

    def setUp(self):
        self.saved = sr.REVIEW_TIMEOUT, sr.RETRY_PAUSE
        sr.REVIEW_TIMEOUT, sr.RETRY_PAUSE = 0.3, 0

    def tearDown(self):
        sr.REVIEW_TIMEOUT, sr.RETRY_PAUSE = self.saved
        self.fake.close()

    def test_the_review_is_requested_as_a_stream_with_a_token_cap(self):
        self.fake = FakeSoclaas(['looks fine'])
        sr.request_review(self.fake.client, {'model': 'm', 'messages': []})
        self.assertIs(self.fake.bodies[0]['stream'], True)
        self.assertEqual(self.fake.bodies[0]['max_tokens'], sr.REVIEW_MAX_TOKENS)

    def test_a_streamed_answer_is_put_back_together(self):
        self.fake = FakeSoclaas([('sse', [chunk('looks'), chunk(' fine'), chunk(finish='stop'), '[DONE]'])])
        self.assertEqual(sr.completion_text(sr.request_review(self.fake.client, {})), 'looks fine')

    def test_a_streamed_answer_that_stops_early_is_not_a_review(self):
        self.fake = FakeSoclaas([('sse', [chunk('looks'), chunk(finish='length'), '[DONE]'])])
        with self.assertRaises(sr.ReviewError) as caught:
            sr.completion_text(sr.request_review(self.fake.client, {}))
        self.assertIn('did not finish normally', str(caught.exception))

    def test_an_error_inside_the_stream_is_reported_without_its_body(self):
        self.fake = FakeSoclaas([('sse', [chunk('looks'), {'error': {'message': 'secret upstream detail'}}])])
        with self.assertRaises(sr.ReviewError) as caught:
            sr.request_review(self.fake.client, {})
        self.assertIn('reported an error', str(caught.exception))
        self.assertNotIn('secret upstream detail', str(caught.exception))

    def test_the_review_request_is_retried_once_after_a_502(self):
        self.fake = FakeSoclaas([502, 'looks fine'])
        self.assertEqual(sr.completion_text(sr.request_review(self.fake.client, {})), 'looks fine')
        self.assertEqual(self.fake.calls, 2)

    def test_the_review_request_is_retried_once_after_a_504(self):
        self.fake = FakeSoclaas([504, 'looks fine'])
        self.assertEqual(sr.completion_text(sr.request_review(self.fake.client, {})), 'looks fine')
        self.assertEqual(self.fake.calls, 2)

    def test_a_400_is_not_retried(self):
        self.fake = FakeSoclaas([400])
        with self.assertRaises(sr.APIError):
            sr.request_review(self.fake.client, {})
        self.assertEqual(self.fake.calls, 1)


